import { existsSync } from 'node:fs';
import StyleDictionary from 'style-dictionary';

const lightSources = [
  'tokens/primitive/**/*.tokens.json',
  'tokens/semantic/light.tokens.json',
  'tokens/component/**/*.tokens.json',
];

export default {
  source: lightSources,
  hooks: {
    formats: {
      'pre-tokens/scss-aliases': ({ dictionary }) => {
        const lines = [
          '// Generated by tokens:build — edit tokens/**, not this file.',
          '',
        ];
        for (const token of dictionary.allTokens) {
          const rootTier = token.path[0];
          const varName = token.name;
          if (
            rootTier === 'semantic' ||
            rootTier === 'component' ||
            rootTier === 'layout'
          ) {
            lines.push(`$${varName}: var(--${varName});`);
          } else if (
            rootTier === 'spacing' ||
            rootTier === 'font-size' ||
            rootTier === 'radius' ||
            rootTier === 'rhythm'
          ) {
            const raw = token.$value ?? token.value;
            const val =
              typeof raw === 'object' && raw && 'value' in raw && 'unit' in raw
                ? `${raw.value}${raw.unit}`
                : String(raw);
            lines.push(`$${varName}: ${val};`);
          }
        }
        lines.push('');
        return lines.join('\n');
      },
    },
    actions: {
      'build-dark-theme': {
        do: async () => {
          if (existsSync('tokens/semantic/dark.tokens.json')) {
            const darkSd = new StyleDictionary({
              source: [
                'tokens/primitive/**/*.tokens.json',
                'tokens/semantic/dark.tokens.json',
                'tokens/component/**/*.tokens.json',
              ],
              platforms: {
                cssDark: {
                  transformGroup: 'css',
                  buildPath: 'build/',
                  files: [
                    {
                      destination: 'tokens.dark.css',
                      format: 'css/variables',
                      options: {
                        selector: '[data-theme="dark"]',
                        outputReferences: true,
                      },
                    },
                  ],
                },
              },
            });
            await darkSd.buildAllPlatforms();
          }
        },
        undo: () => {},
      },
    },
  },
  platforms: {
    cssLight: {
      transformGroup: 'css',
      buildPath: 'build/',
      actions: ['build-dark-theme'],
      files: [
        {
          destination: 'tokens.css',
          format: 'css/variables',
          options: {
            selector: ':root',
            outputReferences: true,
          },
        },
      ],
    },
    scssAliases: {
      transformGroup: 'css',
      buildPath: '__STYLES_ROOT__/abstracts/',
      files: [
        {
          destination: '_variables.scss',
          format: 'pre-tokens/scss-aliases',
        },
      ],
    },
  },
};
